import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Summary-Functions-for-Groups-of-Cells.md","filePath":"manual-zh/CTABLES-Summary-Functions-for-Groups-of-Cells.md","lastUpdated":1785684581000}'),o={name:"manual-zh/CTABLES-Summary-Functions-for-Groups-of-Cells.md"};function c(s,t,p,h,n,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h4 id="_15-7-2-2-针对单元格组的汇总函数" tabindex="-1">15.7.2.2 针对单元格组的汇总函数 <a class="header-anchor" href="#_15-7-2-2-针对单元格组的汇总函数" aria-label="Permalink to &quot;15.7.2.2 针对单元格组的汇总函数&quot;">​</a></h4><p>这些汇总函数在用户选定、并作为函数名一部分指定的输出区域内，对多个单元格进行汇总。支持以下基本区域，按从大到小的顺序排列：</p><p><code>TABLE</code></p><p>一个_小节（section）_。堆叠变量将输出的各个小节彼此分隔开。一个小节可能跨越多个层。</p><p><code>LAYER</code></p><p>单个层内的一个小节。</p><p><code>SUBTABLE</code></p><p>一个_子表（subtable）_，其内容为单个层内最内层行变量与最内层列变量配对形成的单元格。</p><p>下面展示了表表达式 <code>hasBeenPassengerOfDesignatedDriver &gt; hasBeenPassengerOfDrunkDriver BY isLicensedDriver &gt; hasHostedEventWithAlcohol + hasBeenDesignatedDriver BY gender</code>8 的输出是如何被划分为 <code>TABLE</code>、<code>LAYER</code> 和 <code>SUBTABLE</code> 区域的。表 ID 的每个唯一值对应一个小节，层 ID 和子表 ID 同理。因此，该输出包含两个 <code>TABLE</code> 区域（一个对应 <code>isLicensedDriver</code>，一个对应 <code>hasBeenDesignatedDriver</code>）、四个 <code>LAYER</code> 区域（对应那两个变量，按层计数），以及 12 个 <code>SUBTABLE</code> 区域。</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th></th><th>Yes</th><th>No</th><th>Yes</th><th>No</th><th></th><th></th></tr></thead><tbody><tr><td>Male</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>licensed</td><td>desDrv</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>hostAlc</td><td>hostAlc</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Yes</td><td>No</td><td>Yes</td><td>No</td><td></td><td></td></tr><tr><td>desPas</td><td>Yes</td><td>druPas</td><td>Yes</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>1</td><td>1</td><td>2</td><td>2</td><td>3</td><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>No</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>1</td><td>1</td><td>2</td><td>2</td><td>3</td><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>No</td><td>druPas</td><td>Yes</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>4</td><td>4</td><td>5</td><td>5</td><td>6</td><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>No</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>4</td><td>4</td><td>5</td><td>5</td><td>6</td><td>6</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><code>CTABLES</code> 还支持以下区域，用于在一个小节内进一步细分某个子表或某个层：</p><p><code>LAYERROW</code><code>LAYERCOL</code></p><p>分别是某个小节某一层中的一行或一列。</p><p><code>ROW</code><code>COL</code></p><p>分别是某个子表中的一行或一列。</p><p>针对上述每个区域，分类变量和标度变量均可使用以下单元格组汇总函数：</p><p><code>_area_ PCT</code> 或 <code>_area_ PCT.COUNT</code>（“ <em>Area</em> %”，PCT40.1）</p><p>区域内总计数的百分比。</p><p><code>_area_ PCT.VALIDN</code>（“ <em>Area</em> Valid N %”，PCT40.1）</p><p>区域内有效值总计数的百分比。</p><p><code>_area_ PCT.TOTALN</code>（“ <em>Area</em> Total N %”，PCT40.1）</p><p>区域内所有值总计数的百分比。</p><p>标度变量以及分类变量的合计与小计还可使用以下额外的单元格组汇总函数：</p><p><code>_area_ PCT.SUM</code>（“ <em>Area</em> Sum %”，PCT40.1）</p><p>区域内各值之和的百分比。</p><h4 id="脚注" tabindex="-1">脚注 <a class="header-anchor" href="#脚注" aria-label="Permalink to &quot;脚注&quot;">​</a></h4><h5 id="_8" tabindex="-1">(8) <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;(8)&quot;">​</a></h5><p>这不一定是一个有意义的表。为了便于阅读，这里使用了简短的变量标签。</p>',28)])])}const u=d(o,[["render",c]]);export{_ as __pageData,u as default};
